import{_ as n,a0 as o,w as p,s as l,ao as u,I as s,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const G=JSON.parse('{"title":"Linux 有问必答：如何解决 Linux 上的 Wireshark 界面僵死 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何解决 Linux 上的 Wireshark 界面僵死 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何解决 Linux 上的 Wireshark 界面僵死 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何解决 Linux 上的 Wireshark 界面僵死 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150817 Linux FAQs with Answers--How to fix Wireshark GUI freeze on Linux desktop","title":"Linux 有问必答：如何解决 Linux 上的 Wireshark 界面僵死","tag":"201509","desc":""},"relativePath":"201509/20150817 Linux FAQs with Answers--How to fix Wireshark GUI freeze on Linux desktop.md","filePath":"[post].md"}'),d={name:"201509/20150817 Linux FAQs with Answers--How to fix Wireshark GUI freeze on Linux desktop.md"};function k(h,e,L,x,_,f){const r=o("Link");return p(),l("div",null,[e[13]||(e[13]=u(`<h1 id="linux-有问必答-如何解决-linux-上的-wireshark-界面僵死" tabindex="-1">Linux 有问必答：如何解决 Linux 上的 Wireshark 界面僵死 <a class="header-anchor" href="#linux-有问必答-如何解决-linux-上的-wireshark-界面僵死" aria-label="Permalink to “Linux 有问必答：如何解决 Linux 上的 Wireshark 界面僵死”">​</a></h1><blockquote><p><strong>问题</strong>: 当我试图在 Ubuntu 上的 Wireshark 中打开一个 pre-recorded 数据包转储时，它的界面突然死机，在我运行 Wireshark 的终端出现了下面的错误和警告。我该如何解决这个问题？</p></blockquote><pre><code>(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GObject&#39;
(wireshark:3480): GLib-GObject-CRITICAL **: g_object_set_qdata_full: assertion &#39;G_IS_OBJECT (object)&#39; failed
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkRange&#39;
(wireshark:3480): Gtk-CRITICAL **: gtk_range_get_adjustment: assertion &#39;GTK_IS_RANGE (range)&#39; failed
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkOrientable&#39;
(wireshark:3480): Gtk-CRITICAL **: gtk_orientable_get_orientation: assertion &#39;GTK_IS_ORIENTABLE (orientable)&#39; failed
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkScrollbar&#39;
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkWidget&#39;
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GObject&#39;
(wireshark:3480): GLib-GObject-CRITICAL **: g_object_get_qdata: assertion &#39;G_IS_OBJECT (object)&#39; failed
(wireshark:3480): Gtk-CRITICAL **: gtk_widget_set_name: assertion &#39;GTK_IS_WIDGET (widget)&#39; failed
</code></pre><p>Wireshark 是一个基于 GUI 的数据包捕获和嗅探工具。该工具被网络管理员普遍使用，网络安全工程师或开发人员对于各种任务的数据包级的网络分析是必需的，例如在网络故障，漏洞测试，应用程序调试，或逆向协议工程是必需的。 Wireshark 允许实时记录数据包，并通过便捷的图形用户界面浏览他们的协议首部和有效负荷。</p><p><img src="https://farm1.staticflickr.com/722/20584224675_f4d7a59474_c.jpg" alt=""></p><p>这是 Wireshark 的 UI，尤其是在 Ubuntu 桌面下运行时，当你向上或向下滚动分组列表视图时，或开始加载一个 pre-recorded 包转储文件时，有时会挂起或冻结，并出现以下错误。</p><p><img src="https://farm1.staticflickr.com/589/20062177334_47c0f2aeae_c.jpg" alt=""></p><p>显然，这个错误是由 Wireshark 和叠加滚动条之间的一些不兼容造成的，在最新的 Ubuntu 桌面还没有被解决（例如，Ubuntu 15.04 的桌面）。</p><p>一种避免 Wireshark 的 UI 卡死的办法就是 <strong>暂时禁用叠加滚动条</strong>。在 Wireshark 上有两种方法来禁用叠加滚动条，这取决于你在桌面上如何启动 Wireshark 的。</p><h3 id="命令行解决方法" tabindex="-1">命令行解决方法 <a class="header-anchor" href="#命令行解决方法" aria-label="Permalink to “命令行解决方法”">​</a></h3><p>叠加滚动条可以通过设置&quot;<strong>LIBOVERLAY_SCROLLBAR</strong>&quot;环境变量为“0”来被禁止。</p><p>所以，如果你是在终端使用命令行启动 Wireshark 的，你可以在 Wireshark 中禁用叠加滚动条，如下所示。</p><p>打开你的 .bashrc 文件，并定义以下 alias。</p><pre><code>alias wireshark=&quot;LIBOVERLAY_SCROLLBAR=0 /usr/bin/wireshark&quot;
</code></pre><h3 id="桌面启动解决方法" tabindex="-1">桌面启动解决方法 <a class="header-anchor" href="#桌面启动解决方法" aria-label="Permalink to “桌面启动解决方法”">​</a></h3><p>如果你是使用桌面启动器启动的 Wireshark，你可以编辑它的桌面启动器文件。</p><pre><code>$ sudo vi /usr/share/applications/wireshark.desktop
</code></pre><p>查找以&quot;Exec&quot;开头的行，并如下更改。</p><pre><code>Exec=env LIBOVERLAY_SCROLLBAR=0 wireshark %f
</code></pre><p>虽然这种解决方法可以在系统级帮助到所有桌面用户，但升级 Wireshark 就没用了。如果你想保留修改的 .desktop 文件，如下所示将它复制到你的主目录。</p><pre><code>$ cp /usr/share/applications/wireshark.desktop ~/.local/share/applications/ 
</code></pre><hr>`,22)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),i(r,{href:"http://ask.xmodulo.com/fix-wireshark-gui-freeze-linux-desktop.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/fix-wireshark-gui-freeze-linux-desktop.html",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),i(r,{href:"http://ask.xmodulo.com/author/nanni"},{default:a(()=>[...e[2]||(e[2]=[t("Dan Nanni",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),i(r,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...e[3]||(e[3]=[t("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),i(r,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),i(r,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const g=n(d,[["render",k]]);export{G as __pageData,g as default};
